import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { useEffect, useRef, useState, useCallback } from 'react';

interface UseFrameSequenceProps {
  frameCount: number;
  pathPrefix: string;
  extension?: string;
  onProgress?: (progress: number) => void;
}

export function useFrameSequence({
  frameCount,
  pathPrefix,
  extension = 'webp',
  onProgress,
}: UseFrameSequenceProps) {
  const [isLoaded, setIsLoaded] = useState(false);
  const [loadProgress, setLoadProgress] = useState(0);
  const imagesRef = useRef<HTMLImageElement[]>([]);
  const currentFrameRef = useRef(0);

  const preloadImages = useCallback(async () => {
    const loadedImages: HTMLImageElement[] = [];
    let loadedCount = 0;

    const loadImage = (index: number): Promise<HTMLImageElement> => {
      return new Promise((resolve, reject) => {
        const img = new Image();
        const frameNumString = String(index + 1).padStart(4, '0');
        img.src = `${pathPrefix}/frame_${frameNumString}.${extension}`;
        img.onload = () => {
          loadedCount++;
          setLoadProgress(Math.round((loadedCount / frameCount) * 100));
          resolve(img);
        };
        img.onerror = reject;
      });
    };

    try {
      for (let i = 0; i < frameCount; i++) {
        const img = await loadImage(i);
        loadedImages[i] = img;
      }
      imagesRef.current = loadedImages;
      setIsLoaded(true);
    } catch (err) {
      console.error('Failed to load cinematic frame sequence', err);
    } 
  }, [frameCount, pathPrefix, extension]);

  useEffect(() => {
    preloadImages();
  }, [preloadImages]);

  const renderFrame = useCallback((canvas: HTMLCanvasElement, progress: number) => {
    if (!isLoaded || imagesRef.current.length === 0) return;

    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const targetFrame = Math.min(
      frameCount - 1,
      Math.floor(progress * frameCount)
    );

    currentFrameRef.current = targetFrame;
    const img = imagesRef.current[targetFrame];

    if (img) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Object-fit: cover calculation
      const hRatio = canvas.width / img.width;
      const vRatio = canvas.height / img.height;
      const ratio = Math.max(hRatio, vRatio);
      const centerShiftX = (canvas.width - img.width * ratio) / 2;
      const centerShiftY = (canvas.height - img.height * ratio) / 2;

      ctx.drawImage(
        img,
        0,
        0,
        img.width,
        img.height,
        centerShiftX,
        centerShiftY,
        img.width * ratio,
        img.height * ratio
      );
    }

    if (onProgress) {
      onProgress(progress);
    }
  }, [isLoaded, frameCount, onProgress]);

  return {
    isLoaded,
    loadProgress,
    renderFrame,
    currentFrame: currentFrameRef.current,
  };
}

import { create } from 'zustand';

export interface HUDChapter {
  id: number;
  title: string;
  subtitle: string;
  telemetry: {
    coreTemp: string;
    hydraulicPressure: string;
    servoVoltage: string;
    stabilityIndex: string;
  };
  activeRange: [number, number];
}

interface HUDState {
  currentProgress: number;
  activeChapterIndex: number;
  isGlitching: boolean;
  audioEnabled: boolean;
  chapters: HUDChapter[];
  setProgress: (progress: number) => void;
  setGlitching: (glitching: boolean) => void;
  toggleAudio: () => void;
}

const DEFAULT_CHAPTERS: HUDChapter[] = [
  {
    id: 0,
    title: 'PHASE 01: HEAVY HAULER',
    subtitle: 'Autonomous Class-IV chassis locked in transit configuration.',
    telemetry: { coreTemp: '42.4°C', hydraulicPressure: '3400 PSI', servoVoltage: '24V', stabilityIndex: '99.8%' },
    activeRange: [0.0, 0.25],
  },
  {
    id: 1,
    title: 'PHASE 02: KINETIC DEPLOYMENT',
    subtitle: 'Initiating hydraulic decoupling and sub-frame rotation.',
    telemetry: { coreTemp: '68.9°C', hydraulicPressure: '5800 PSI', servoVoltage: '48V', stabilityIndex: '84.2%' },
    activeRange: [0.25, 0.55],
  },
  {
    id: 2,
    title: 'PHASE 03: BIPEDAL RECONFIGURATION',
    subtitle: 'Spine alignment active. Gyroscopic stabilization engaged.',
    telemetry: { coreTemp: '89.1°C', hydraulicPressure: '8200 PSI', servoVoltage: '72V', stabilityIndex: '92.5%' },
    activeRange: [0.55, 0.85],
  },
  {
    id: 3,
    title: 'PHASE 04: APEX PREDATOR',
    subtitle: 'Combat matrix online. Full humanoid articulation achieved.',
    telemetry: { coreTemp: '104.5°C', hydraulicPressure: '12000 PSI', servoVoltage: '120V', stabilityIndex: '100.0%' },
    activeRange: [0.85, 1.0],
  },
];

export const useHUDStore = create<HUDState>((set, get) => ({
  currentProgress: 0,
  activeChapterIndex: 0,
  isGlitching: false,
  audioEnabled: false,
  chapters: DEFAULT_CHAPTERS,
  setProgress: (progress: number) => {
    const { chapters, activeChapterIndex } = get();
    const currentChapter = chapters.findIndex(
      (ch) => progress >= ch.activeRange[0] && progress < ch.activeRange[1]
    );

    const newIndex = currentChapter !== -1 ? currentChapter : activeChapterIndex;

    set({
      currentProgress: progress,
      activeChapterIndex: newIndex,
      isGlitching: Math.abs(progress - get().currentProgress) > 0.05,
    });
  },
  setGlitching: (isGlitching: boolean) => set({ isGlitching }),
  toggleAudio: () => set((state) => ({ audioEnabled: !state.audioEnabled })),
}));
